import re
from datetime import date

_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10,
    "november": 11, "december": 12,
}


def _make(y: int, m: int, d: int):
    try:
        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_num(word: str):
    return _MONTHS.get(word.lower().rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s.strip())
    if not t:
        return "INVALID"

    result = None

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        result = _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact: YYYYMMDD
    if result is None:
        m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
        if m:
            result = _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Day-first numeric (observed convention: DD/MM/YYYY):
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    if result is None:
        m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
        if m:
            result = _make(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Named month, day first: "5 March 2024", "05-Mar-2024", "5th of March 2024"
    if result is None:
        m = re.fullmatch(
            r"(\d{1,2})(?:st|nd|rd|th)?(?:\s+of)?[\s\-]+([A-Za-z]+\.?)[\s\-,]+(\d{4})",
            t,
        )
        if m:
            mon = _month_num(m.group(2))
            if mon:
                result = _make(int(m.group(3)), mon, int(m.group(1)))

    # Named month, day after: "March 5, 2024", "Mar 5 2024"
    if result is None:
        m = re.fullmatch(
            r"([A-Za-z]+\.?)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})",
            t,
        )
        if m:
            mon = _month_num(m.group(1))
            if mon:
                result = _make(int(m.group(3)), mon, int(m.group(2)))

    return result if result is not None else "INVALID"

import re
import datetime

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Assumption: ambiguous numeric dates (e.g. 03/04/2021) are read day-first.
_NUMERIC_DAY_FIRST = True


def _to_iso(y: int, m: int, d: int) -> str:
    """Return ISO date string if (y, m, d) is a real calendar date, else 'INVALID'."""
    try:
        return datetime.date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = s.strip()

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Numeric DD-MM-YYYY, DD/MM/YYYY, DD.MM.YYYY (or MM-first if configured)
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(3)), int(m.group(4))
        d, mo = (a, b) if _NUMERIC_DAY_FIRST else (b, a)
        return _to_iso(y, mo, d)

    # "March 4, 2021", "Mar 4th 2021", "March 4 2021"
    m = re.fullmatch(r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", t)
    if m:
        mo = _MONTHS.get(m.group(1).lower())
        if mo is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), mo, int(m.group(2)))

    # "4 March 2021", "4th of March, 2021"
    m = re.fullmatch(r"(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([A-Za-z]+)\.?,?\s+(\d{4})", t)
    if m:
        mo = _MONTHS.get(m.group(2).lower())
        if mo is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), mo, int(m.group(1)))

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)"
    r"(?:day|nesday|sday|urday)?\.?,?\s+",
    re.IGNORECASE,
)

_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_DMY_NUM = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")
_DMY_TXT = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[ \-]*([A-Za-z]{3,9})\.?,?[ \-]+(\d{4})",
    re.IGNORECASE,
)
_MDY_TXT = re.compile(
    r"([A-Za-z]{3,9})\.?[ \-]+(\d{1,2})(?:st|nd|rd|th)?,?[ \-]+(\d{4})",
    re.IGNORECASE,
)


def _make(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s).strip()
    t = _WEEKDAY_PREFIX.sub("", t, count=1).strip()
    if not t:
        return "INVALID"

    m = _ISO.fullmatch(t)
    if m:
        y, mo, d = (int(x) for x in m.groups())
        return _make(y, mo, d)

    m = _COMPACT.fullmatch(t)
    if m:
        y, mo, d = (int(x) for x in m.groups())
        return _make(y, mo, d)

    m = _DMY_NUM.fullmatch(t)
    if m:
        d, mo, y = (int(x) for x in m.groups())
        return _make(y, mo, d)

    m = _DMY_TXT.fullmatch(t)
    if m:
        d, name, y = m.groups()
        mo = _month_number(name)
        if mo is None:
            return "INVALID"
        return _make(int(y), mo, int(d))

    m = _MDY_TXT.fullmatch(t)
    if m:
        name, d, y = m.groups()
        mo = _month_number(name)
        if mo is None:
            return "INVALID"
        return _make(int(y), mo, int(d))

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sept": 9, "sep": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|mon|tuesday|tues|tue|wednesday|wed|thursday|thurs|thur|thu"
    r"|friday|fri|saturday|sat|sunday|sun)\.?,?\s+",
    re.IGNORECASE,
)
_ORDINAL = r"(?:st|nd|rd|th)?"


def _build(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = s.strip()
    text = re.sub(r"\s+", " ", text)
    text = text.replace(",", " ")
    text = re.sub(r"\.(?=\s|$)", "", text)  # drop abbreviation dots: "Jan. 5" -> "Jan 5"
    text = re.sub(r"\s+", " ", text).strip()
    text = _WEEKDAY_PREFIX.sub("", text, count=1)

    if not text:
        return "INVALID"

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (1- or 2-digit month/day)
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", text)
    if m:
        y, mo, d = (int(g) for g in m.groups())
        return _build(y, mo, d)

    # Numeric, day-first: DD/MM/YYYY (assumed convention for ambiguous numerics)
    m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})", text)
    if m:
        d, mo, y = (int(g) for g in m.groups())
        return _build(y, mo, d)

    # Textual, day first: "5th March 2024", "5 of March 2024"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORDINAL + r"\s+(?:of\s+)?([A-Za-z]+)\s+(\d{4})",
        text,
        re.IGNORECASE,
    )
    if m:
        d = int(m.group(1))
        mo = _month_number(m.group(2))
        if mo is None:
            return "INVALID"
        return _build(int(m.group(3)), mo, d)

    # Textual, month first: "March 5th 2024", "March 5 2024"
    m = re.fullmatch(
        r"([A-Za-z]+)\s+(\d{1,2})" + _ORDINAL + r"\s+(\d{4})",
        text,
        re.IGNORECASE,
    )
    if m:
        mo = _month_number(m.group(1))
        if mo is None:
            return "INVALID"
        return _build(int(m.group(3)), mo, int(m.group(2)))

    return "INVALID"
